282	void set_params_splitkv(Flash_fwd_params &params, const int batch_size,
283	    const int num_heads, const int head_size, const int max_seqlen_k, const int max_seqlen_q,
284	    const int head_size_rounded, const float p_dropout,
285	    const int num_splits, cudaDeviceProp *dprops, struct c10::TensorOptions opts) {
286	
287	    // This needs to match with run_mha_fwd_splitkv_dispatch
288	    // TODO
289	    // const int block_n = head_size <= 64 ? 256 : (head_size <= 128 ? 128 : 64);
290	    const int block_n = 256;
291	    const int num_n_blocks = (max_seqlen_k + block_n - 1) / block_n;
292	    // Technically kBlockM = 64 only for the splitKV kernels, not the standard kernel.
293	    // In any case we don't expect seqlen_q to be larger than 64 for inference.
294	    const int num_m_blocks = (max_seqlen_q + 64 - 1) / 64;
295	    params.num_splits = num_splits;
296	    if (p_dropout == 0.0f) {  // SplitKV is not implemented for dropout
297	        if (num_splits < 1) {
298	            // We multiply number of SMs by 2 to hard-code the fact that we're using 128 threads per block.
299	            params.num_splits = num_splits_heuristic(batch_size * num_heads * num_m_blocks, dprops->multiProcessorCount * 2, num_n_blocks, 128);
300	            // printf("num_splits = %d\n", params.num_splits);
301	            // params.num_splits= 1;
302	        }
303	        params.num_splits += 1;  // We need to add 1 for residual kernel.
304	        // printf("num_splits = %d\n", params.num_splits);
305	        if (params.num_splits > 1) {
306	            at::Tensor softmax_lse_accum = torch::empty({params.num_splits, batch_size, num_heads, max_seqlen_q}, opts.dtype(at::kFloat));
307	            at::Tensor out_accum = torch::empty({params.num_splits, batch_size, num_heads, max_seqlen_q, head_size_rounded}, opts.dtype(at::kFloat));
308	            params.softmax_lseaccum_ptr = softmax_lse_accum.data_ptr();
309	            params.oaccum_ptr = out_accum.data_ptr();
310	        }
311	        TORCH_CHECK(params.num_splits <= 128, "num_splits > 128 not supported");
312	    }
313	}
