602	template <int num_bits>
603	void kvcache_qpack(const at::Tensor &k, at::Tensor &k_pack, at::Tensor &k_params,
604	                   const at::Tensor &v, at::Tensor &v_pack, at::Tensor &v_params,
605	                   c10::optional<at::Tensor> &block_table_,
606	                   const at::Tensor &cu_seqlens_k, 
607	                   const int max_seqlen_k,
608	                   const std::string quant_mode,
609	                   const int group_size
610	                   ) {
611	
612	    auto k_dtype = k.dtype();
613	    TORCH_CHECK(k_dtype == torch::kFloat16 || k_dtype == torch::kBFloat16,
614	                "FlashAttention only support fp16 and bf16 data type");
615	
616	    TORCH_CHECK(cu_seqlens_k.dtype() == torch::kInt32, "cu_seqlens_k must have dtype int32");
617	
618	    CHECK_DEVICE(k); CHECK_DEVICE(v);
619	    CHECK_DEVICE(cu_seqlens_k);
620	    TORCH_CHECK(k.stride(-1) == 1, "Input tensor must have contiguous last dimension");
621	    TORCH_CHECK(v.stride(-1) == 1, "Input tensor must have contiguous last dimension");
622	    CHECK_CONTIGUOUS(cu_seqlens_k);
623	
624	    at::Tensor block_table;
625	    const bool paged_KV = block_table_.has_value();
626	    if (paged_KV) {
627	        block_table = block_table_.value();
628	        CHECK_DEVICE(block_table);
629	        TORCH_CHECK(block_table.dtype() == torch::kInt32, "block_table must have dtype torch.int32");
630	        TORCH_CHECK(block_table.stride(-1) == 1, "block_table must have contiguous last dimension");
631	    }
632	    
633	    const auto sizes = k.sizes();
634	
635	    const int batch_size  = cu_seqlens_k.numel() - 1;
636	    int num_heads         = paged_KV ? sizes[2] : sizes[1];
637	    const int head_size   = paged_KV ? sizes[3] : sizes[2];
638	    const int num_heads_k = paged_KV ? k.size(2) : k.size(1);
639	
640	    const int max_num_blocks_per_seq = !paged_KV ? 0 : block_table.size(1);
641	    const int num_blocks             = !paged_KV ? 0 : k.size(0);
642	    const int page_block_size        = !paged_KV ? 1 : k.size(1);
643	    const int page_block_size_pack   = !paged_KV ? 0 : k_pack.size(1);
644	    const int seqlen_k               = !paged_KV ? k.size(1) : max_num_blocks_per_seq * page_block_size;
645	    const int batch_size_c           = !paged_KV ? k.size(0) : batch_size;
646	
647	    TORCH_CHECK(!paged_KV || page_block_size % 256 == 0, "Paged KV cache block size must be divisible by 256");
648	    TORCH_CHECK(batch_size > 0, "batch size must be positive");
649	    TORCH_CHECK(head_size <= 256, "FlashAttention forward only supports head dimension at most 256");
650	    TORCH_CHECK(head_size % 8 == 0, "query, key, value, and out_ must have a head_size that is a multiple of 8");
651	    TORCH_CHECK(num_heads % num_heads_k == 0, "Number of heads in key/value must divide number of heads in query");
652	    CHECK_SHAPE(cu_seqlens_k, batch_size + 1);
653	
654	    // Otherwise the kernel will be launched from cuda:0 device
655	    // Cast to char to avoid compiler warning about narrowing
656	    at::cuda::CUDAGuard device_guard{(char)k.get_device()};
657	
658	    Flash_fwd_params params;
659	    set_params_fprop_qpack(params,
660	                           batch_size,
661	                           max_seqlen_k,
662	                           num_heads, num_heads_k,
663	                           head_size,
664	                           k, k_pack, k_params,
665	                           v, v_pack, v_params,
666	                           /*cu_seqlens_k_d=*/nullptr,
667	                           quant_mode,
668	                           group_size,
669	                           paged_KV
670	                           );
671	
672	    if (paged_KV) {
673	        params.block_table = block_table.data_ptr<int>();
674	        params.block_table_batch_stride = block_table.stride(0);
675	    }
676	    params.page_block_size      = page_block_size;
677	    params.page_block_size_pack = page_block_size_pack;
678	
679	    if (max_seqlen_k > 0) {
680	        auto stream = at::cuda::getCurrentCUDAStream().stream();
681	        run_kvcache_qpack<num_bits>(params, stream);
682	    } 
683	
684	    return;
685	}
