445	
446	};
447	
448	////////////////////////////////////////////////////////////////////////////////////////////////////
449	
450	template<int kHeadDim_, int kBlockN_, int kNWarps_, int quantmode_=0, int num_bits_=4, int group_size_=128, typename elem_type=cutlass::half_t,
451	         typename Base=Flash_kernel_traits<kHeadDim_, 32, kBlockN_, kNWarps_, elem_type> >
452	struct Flash_qpack_traits : public Base {
453	    using Element                = typename Base::Element;
454	    using ElementKVPack          = cute::uint16_t;
455	    using index_t                = typename Base::index_t;
456	    using SmemCopyAtom           = typename Base::SmemCopyAtom;
457	    using SmemCopyAtomTransposed = typename Base::SmemCopyAtomTransposed;
458	
459	    static constexpr int quant_mode = quantmode_;
460	    static constexpr int group_size = group_size_;
461	    static constexpr int num_bits   = num_bits_;
462	    static constexpr int pack_num   = 16 / num_bits;
463	
464	    // The number of threads.
465	    static constexpr int kNWarps   = kNWarps_;
466	    static constexpr int kNThreads = kNWarps * 32;
467	    
468	    static constexpr int kBlockN           = kBlockN_;
469	    static constexpr int kBlockN_pack      = num_bits   == 4 ? 128 : 256;
470	    static constexpr int kBlockP           = quant_mode == 1 ? kBlockN / pack_num : kBlockN;
471	    static constexpr int kBlockK_params    = quant_mode == 1 ? kBlockN / group_size : kBlockN;
472	    static constexpr int kHeadDim          = kHeadDim_;
473	    static constexpr int kHeadDim_pack     = kHeadDim / pack_num; // TODO
474	    static constexpr int kHeadDim_k        = quant_mode == 1 ? kHeadDim : kHeadDim_pack;
475	    static constexpr int kHeadDim_k_params = quant_mode == 1 ? kHeadDim : kHeadDim / group_size;
476	    static constexpr int kHeadDim_v_params = kHeadDim / group_size;
477	    static_assert(kHeadDim % 32 == 0);
478	    static constexpr int kBlockKSmem = kHeadDim % 64 == 0 ? 64 : 32;
479	    static constexpr int kBlockKGmem = kHeadDim % 128 == 0 ? 128 : (kHeadDim % 64 == 0 ? 64 : 32);
480	    static constexpr int kSwizzle    = kBlockKSmem == 32 ? 2 : 3;
481	
482	    static constexpr int tile_paramsk_g = kBlockN / 32 * (kBlockN / group_size); // TODO: check
483	    static constexpr int tile_paramsk_j = kBlockN / group_size;
484	    static constexpr int tile_paramsk_k = kHeadDim / 16;
485	    static constexpr int tile_paramsv_k = kBlockN / 16;    // TODO: check 128
486	
487	    static constexpr int num_params = kBlockN_pack / group_size;
488	
489	    using TiledMma = TiledMMA<
490	        typename Base::MMA_Atom_Arch,
491	        Layout<Shape<Int<1>,_4,_1>>,  
492	        Tile<Int<16>, _128, _16>>;
493	
494	    using TiledMmaK_i4 = TiledMMA<
495	        typename Base::MMA_Atom_Arch,
496	        Layout<Shape<Int<1>,_4,_1>>,  
497	        Tile<Int<16>, Int<32>, _16>>;
498	
499	    using SmemLayoutAtomKV_SW = decltype(
500	        composition(Swizzle<kSwizzle, 3, 3>{},
501	                    // This has to be kBlockKSmem, using kHeadDim gives wrong results for d=128
502	                    Layout<Shape<_8, Int<kBlockKSmem>>,
503	                           Stride<Int<kBlockKSmem>, _1>>{}));
504	    using SmemLayoutAtomK_tiled = decltype(
505	        make_layout(make_shape(Int<8>{}, Int<kHeadDim>{}),
506	                    make_stride(Int<kHeadDim>{}, Int<1>{})));
507	    using SmemLayoutKV = decltype(tile_to_shape(
508	        SmemLayoutAtomK_tiled{},
509	        Shape<Int<kBlockN>, Int<kHeadDim>>{}));
510	    using SmemLayoutVtransposed = decltype(
511	        composition(SmemLayoutKV{}, make_layout(Shape<Int<kHeadDim>, Int<kBlockN>>{}, GenRowMajor{})));
512	    using SmemLayoutVtransposedNoSwizzle = decltype(get_nonswizzle_portion(SmemLayoutVtransposed{}));
513	
514	    using SmemLayoutKPack = decltype(
515	        make_layout(make_shape(Int<kBlockP>{}, Int<kHeadDim_k>{}),
516	                    make_stride(Int<kHeadDim_k>{}, Int<1>{})));
517	    using SmemLayoutKPacktransposed_ = decltype(
518	        composition(SmemLayoutKPack{}, make_layout(Shape<Int<kHeadDim_k>, Int<kBlockP>>{}, GenRowMajor{})));
519	    using SmemLayoutKPacktransposed = std::conditional_t<
520	        quant_mode == 1,
521	        SmemLayoutKPack,
522	        SmemLayoutKPacktransposed_
523	    >;
524	
525	    using SmemLayoutAtomV = decltype(
526	        make_layout(make_shape(Int<8>{}, Int<kHeadDim_pack>{}),
527	                    make_stride(Int<kHeadDim_pack>{}, Int<1>{})));
528	    using SmemLayoutVPack = decltype(tile_to_shape(
529	        SmemLayoutAtomV{},
530	        Shape<Int<kBlockN>, Int<kHeadDim_pack>>{}));
531	    using SmemLayoutVPacktransposed = decltype(
532	        composition(SmemLayoutVPack{}, make_layout(Shape<Int<kHeadDim_pack>, Int<kBlockN>>{}, GenRowMajor{})));
533	    using SmemLayoutVPacktransposedNoSwizzle = decltype(get_nonswizzle_portion(SmemLayoutVPacktransposed{}));
534	
535	    // TODO: 32 of x can be determined. 
536	    using SmemLayoutReduce_tmp = decltype(
537	        make_layout(make_shape(Int<32>{}, Int<32>{}),
538	                    make_stride(Int<32>{}, Int<1>{})));
539	
540	    using R2SCopyAtom = Copy_Atom<DefaultCopy, Element>;
541	    using R2SCopyAtomPack = Copy_Atom<DefaultCopy, ElementKVPack>;
542	
543	    struct SharedStorage
544	    {
545	        array_aligned<Element, cosize_v<SmemLayoutKV>> smem_K;
546	        array_aligned<Element, cosize_v<SmemLayoutKV>> smem_V;
547	        array_aligned<ElementKVPack, cosize_v<SmemLayoutKPack>> smem_Kpack;
548	        array_aligned<ElementKVPack, cosize_v<SmemLayoutVPack>> smem_Vpack;
549	        array_aligned<Element, cosize_v<SmemLayoutReduce_tmp>> smem_reduce_tmp;
550	    };
551	    static constexpr int kSmemSize = int(sizeof(SharedStorage));
552	
553	    static constexpr int kGmemElemsPerLoad = sizeof(cute::uint128_t) / sizeof(Element);
554	    static_assert(kHeadDim % kGmemElemsPerLoad == 0, "kHeadDim must be a multiple of kGmemElemsPerLoad");
555	    static constexpr int kGmemThreadsPerRow = kBlockKSmem / kGmemElemsPerLoad;
556	    static_assert(kNThreads % kGmemThreadsPerRow == 0, "kNThreads must be a multiple of kGmemThreadsPerRow");
557	    using GmemLayoutAtom = Layout<Shape <Int<kNThreads / kGmemThreadsPerRow>, Int<kGmemThreadsPerRow>>,
558	                                  Stride<Int<kGmemThreadsPerRow>, _1>>;
559	
560	    // We use CACHEGLOBAL instead of CACHEALWAYS for both Q and K/V, since we won't be reading
561	    // from the same address by the same threadblock. This is slightly faster.
562	    using GmemTiledCopyQKV = decltype(
563	        make_tiled_copy(Copy_Atom<SM80_CP_ASYNC_CACHEGLOBAL<cute::uint128_t>, Element>{},
564	                        GmemLayoutAtom{},
565	                        Layout<Shape<_1, _8>>{}));  // Val layout, 8 vals per read
566	    using GmemTileCopyK_Pack = decltype(
567	        make_tiled_copy(Copy_Atom<DefaultCopy, ElementKVPack>{},
568	                        make_layout(make_shape(_32{}, _4{}), make_stride(_4{}, _1{})),
569	                        Layout<Shape<_1, _8>>{}));  // Val layout, 8 vals per store
570	    using GmemTileCopyV_Pack = decltype(
571	        make_tiled_copy(Copy_Atom<DefaultCopy, ElementKVPack>{},
572	                        make_layout(make_shape(_64{}, _2{}), make_stride(_2{}, _1{})),
573	                        Layout<Shape<_1, _8>>{}));  // Val layout, 8 vals per store
574	};
